import { PERKS, PERK_IDS } from "@/lib/tower/sim/balance";
import { aimAt, castVolley, chooseUpgrade, createRun, nearestEnemy, step, STEP } from "@/lib/tower/sim/run";
import { buildSpawns } from "@/lib/tower/sim/waves";
import type { PerkLevels } from "@/lib/tower/sim/types";

/** Generated by real sim ticks: boss, status effects, ricochets, caltrops, projectiles and pending spawns. */
export function richRun(seed = 445) {
  const perks = Object.fromEntries(PERK_IDS.map((id) => [id, PERKS[id].max])) as PerkLevels;
  const run = createRun(seed, perks);
  while (run.phase === "choosing") chooseUpgrade(run, run.choices[0]);
  Object.assign(run.upgrades, { damage: 1, range: 3, multishot: 1, pierce: 1, ricochet: 1, fire: 1, frost: 1, caltrops: 2, regen: 1 });
  run.wave = 20;
  run.spawns = buildSpawns(run.wave, run);
  for (let tick = 0; tick < 1500 && run.phase === "playing"; tick += 1) {
    const target = nearestEnemy(run);
    if (tick % 50 === 0) aimAt(run, tick % 100 ? 5 : target?.x ?? 180, tick % 100 ? 350 : target?.y ?? 300);
    if (tick === 900) castVolley(run, target?.x ?? 180, target?.y ?? 300);
    step(run, STEP);
  }
  const target = nearestEnemy(run);
  castVolley(run, target?.x ?? 180, target?.y ?? 300);
  return run;
}
